			connection.commit();
			buildAdjacency(route);
			TupleQuery selected = query(connection, "USE GRAPH `urn:gql:one` " + anchored(OUTGOING));
			selected.setBinding("start", ALICE);
			assertThat(values(selected, "b")).containsExactly(BOB);

			TupleQuery overridden = query(connection, anchored(OUTGOING));
