	@ParameterizedTest
	@EnumSource(Route.class)
	void interruptedQueryReleasesItsReadResources(Route route) {
		open(route);
		seedDiamond(route);
		try (RepositoryConnection connection = repository.getConnection()) {
			TupleQuery query = query(connection, OUTGOING);
			Thread.currentThread().interrupt();
			try {
				assertThatThrownBy(() -> values(query, "b")).isInstanceOf(QueryEvaluationException.class);
			} finally {
				Thread.interrupted();
			}
			assertThat(values(query, "b")).containsExactlyInAnyOrder(BOB, CAROL, DORA, DORA);
		}
	}

