	@ParameterizedTest
	@EnumSource(value = Route.class, names = { "ADJACENCY", "NATIVE_ADJACENCY" })
	void gqlTraversalsActuallyUseAdjacency(Route route) {
		open(route);
		seedDiamond(route);
		try (RepositoryConnection connection = repository.getConnection()) {
			TupleQuery query = query(connection, anchored(OUTGOING));
			query.setBinding("start", ALICE);
			long before = AdjacencyEngagementTestAccess.lookupHits(store);
			assertThat(values(query, "b")).containsExactlyInAnyOrder(BOB, CAROL);
			assertThat(AdjacencyEngagementTestAccess.lookupHits(store))
					.as("the GQL query itself must consume adjacency, not merely build an unused index")
					.isGreaterThan(before);
		}
	}

	private void open(Route route) {
		store = new LmdbStore(directory.toFile(), new LmdbStoreConfig("spoc,posc")
				.setNativeEvaluationEnabled(route.nativeEvaluation)
				.setDirectAdjacencyEnabled(route.adjacency)
				.setDirectAdjacencyMode(route.adjacency ? DirectAdjacencyMode.PREFER : DirectAdjacencyMode.DISABLED)
				.setDirectAdjacencyBuildOnStart(false)
				.setDirectAdjacencyMaxBytes(LmdbStoreConfig.DIRECT_ADJACENCY_MIN_EXPLICIT_BYTES));
		repository = new SailRepository(store);
		repository.init();
	}

	private void seedDiamond(Route route) {
		try (RepositoryConnection connection = repository.getConnection()) {
			connection.begin();
			for (IRI person : List.of(ALICE, BOB, CAROL, DORA)) {
				connection.add(person, RDF.TYPE, PERSON);
			}
			connection.add(ALICE, KNOWS, BOB);
			connection.add(ALICE, KNOWS, CAROL);
			connection.add(BOB, KNOWS, DORA);
			connection.add(CAROL, KNOWS, DORA);
			connection.commit();
		}
		buildAdjacency(route);
	}

	private void buildAdjacency(Route route) {
		if (route.adjacency) {
			assertThat(AdjacencyEngagementTestAccess.buildNow(store)).isTrue();
		}
	}

	private static TupleQuery query(RepositoryConnection connection, String text) {
		TupleQuery query = connection.prepareTupleQuery(GQL, text);
		query.setIncludeInferred(false);
		return query;
	}

	private static String anchored(String text) {
		return text.replace(" RETURN ", " WHERE a = $start RETURN ");
	}

	private static List<Value> values(TupleQuery query, String name) {
		List<Value> rows = new ArrayList<>();
		try (var result = query.evaluate()) {
			while (result.hasNext()) {
				rows.add(result.next().getValue(name));
			}
		}
		return rows;
	}

	private static IRI iri(String localName) {
		return VF.createIRI("urn:gql:" + localName);
	}
